mapper.sql:
WHERE s.deleted = FALSE

    AND (s.session_no ILIKE #{q.keywordLike} ESCAPE '\'
      OR s.session_name ILIKE #{q.keywordLike} ESCAPE '\')


    AND s.plan_id = #{q.planId}


    AND s.course_id = #{q.courseId}


    AND s.lecturer_id = #{q.lecturerId}


    AND s.session_state = #{q.sessionState}


    AND s.training_form = #{q.trainingForm}


    AND s.training_date >= #{q.dateFrom}


    AND s.training_date <= #{q.dateTo}




            AND EXISTS (SELECT 1 FROM dtl_attendance a
                         WHERE a.session_id = s.id AND a.deleted = FALSE)


            AND NOT EXISTS (SELECT 1 FROM dtl_attendance a
                             WHERE a.session_id = s.id AND a.deleted = FALSE)
